package io.knowledgebrain.planning;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;import tools.jackson.databind.json.JsonMapper;
import static io.knowledgebrain.planning.GoalController.*;
@RestController @ConditionalOnProperty(name="brain.planning.api.enabled",havingValue="true") @RequestMapping("/api/spaces/{spaceId}/recurrences")
final class RecurrenceController {
 private final RecurrenceStore store;private final SpaceAuthorizationClient authority;private final MeterRegistry metrics;private final String origin;private final JsonMapper json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 RecurrenceController(RecurrenceStore store,SpaceAuthorizationClient authority,MeterRegistry metrics,@Value("${brain.planning.browser-origin}")String origin){this.store=store;this.authority=authority;this.metrics=metrics;this.origin=origin;}
 static String tag(long version){return "\"rc"+version+"\"";}
 static long version(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(h.size()!=1||!h.getFirst().matches("\"rc[1-9][0-9]{0,18}\""))throw ScheduleRules.bad();try{return Long.parseLong(h.getFirst().substring(3,h.getFirst().length()-1));}catch(NumberFormatException e){throw ScheduleRules.bad();}}
 private UUID authorize(UUID space,HttpServletRequest r,boolean write,String trace){if(!r.isSecure())throw ScheduleRules.bad();if(r.getMethod().equals("POST")&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Ambiguous session");token=c.getValue();}return authority.authorize(space,token,write?"SCHEDULE_WRITE":"SCHEDULE_READ","PRIVATE",trace);}

 private tools.jackson.databind.JsonNode body(HttpServletRequest r)throws IOException{if(!MediaType.APPLICATION_JSON_VALUE.equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE);var bytes=r.getInputStream().readNBytes(262145);if(bytes.length>262144)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE);try{var v=json.readTree(bytes);if(v==null||!v.isObject())throw ScheduleRules.bad();return v;}catch(RuntimeException e){throw ScheduleRules.bad();}}
 private RecurrenceRules.Input input(tools.jackson.databind.JsonNode v){try{if(!v.isObject()||v.size()!=11)throw ScheduleRules.bad();for(String f:List.of("title","description","startsLocal","endsLocal","timeZone","frequency","startsOverlap","endsOverlap"))if(!v.path(f).isString())throw ScheduleRules.bad();for(String f:List.of("interval","count"))if(!v.path(f).isIntegralNumber()||!v.path(f).canConvertToInt())throw ScheduleRules.bad();if(!(v.path("taskId").isNull()||v.path("taskId").isString()))throw ScheduleRules.bad();var i=new RecurrenceRules.Input(v.path("title").asString(),v.path("description").asString(),v.path("startsLocal").asString(),v.path("endsLocal").asString(),v.path("timeZone").asString(),v.path("taskId").isNull()?null:ScheduleRules.id(v.path("taskId").asString()),v.path("frequency").asString(),v.path("interval").asInt(),v.path("count").asInt(),v.path("startsOverlap").asString(),v.path("endsOverlap").asString());RecurrenceRules.input(i);return i;}catch(RuntimeException e){throw ScheduleRules.bad();}}
 private ResponseEntity<RecurrenceStore.Series> response(RecurrenceStore.Series v){return ResponseEntity.ok().eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(v);}
 @PostMapping("/preview") ResponseEntity<RecurrenceRules.Preview> preview(@PathVariable String spaceId,HttpServletRequest r)throws IOException{parameters(r,Set.of());UUID space=ScheduleRules.id(spaceId);authorize(space,r,false,parent(r));var p=store.preview(space,input(body(r)));metrics.counter("brain.planning.recurrence.reads","type","preview").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(p);}
 @PostMapping ResponseEntity<RecurrenceStore.Series> create(@PathVariable String spaceId,HttpServletRequest r)throws IOException{parameters(r,Set.of());UUID space=ScheduleRules.id(spaceId);String trace=parent(r);var actor=authorize(space,r,true,trace);var h=Collections.list(r.getHeaders("Idempotency-Key"));if(h.size()!=1||!h.getFirst().matches("[0-9a-f]{32}"))throw ScheduleRules.bad();var b=body(r);if(b.size()!=2||!b.path("previewHash").isString())throw ScheduleRules.bad();var created=store.create(space,actor,h.getFirst(),input(b.path("input")),b.path("previewHash").asString(),trace.substring(3,35));var v=created.recurrence();metrics.counter("brain.planning.recurrence.changes","type",created.replay()?"replayed":"created").increment();return ResponseEntity.status(created.replay()?200:201).header("Location","/api/spaces/"+space+"/recurrences/"+v.recurrenceId()).eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(v);}
 @GetMapping ResponseEntity<RecurrenceStore.Page> list(@PathVariable String spaceId,HttpServletRequest r){parameters(r,Set.of("state","after","limit"));UUID space=ScheduleRules.id(spaceId);authorize(space,r,false,parent(r));var p=store.list(space,Optional.ofNullable(r.getParameter("state")).orElse("ACTIVE"),r.getParameter("after"),(int)number(r.getParameter("limit"),20,100));metrics.counter("brain.planning.recurrence.reads","type","catalog").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(p);}
 @GetMapping("/{recurrenceId}") ResponseEntity<RecurrenceStore.Series> get(@PathVariable String spaceId,@PathVariable String recurrenceId,HttpServletRequest r){parameters(r,Set.of());UUID space=ScheduleRules.id(spaceId),id=ScheduleRules.id(recurrenceId);authorize(space,r,false,parent(r));metrics.counter("brain.planning.recurrence.reads","type","current").increment();return response(store.get(space,id));}
 @GetMapping("/{recurrenceId}/revisions") ResponseEntity<List<RecurrenceStore.Revision>> history(@PathVariable String spaceId,@PathVariable String recurrenceId,HttpServletRequest r){parameters(r,Set.of("before","limit"));UUID space=ScheduleRules.id(spaceId),id=ScheduleRules.id(recurrenceId);authorize(space,r,false,parent(r));metrics.counter("brain.planning.recurrence.reads","type","history").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(space,id,number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)number(r.getParameter("limit"),5,10)));}
 @GetMapping("/{recurrenceId}/cancellation") ResponseEntity<RecurrenceStore.Cancellation> cancellation(@PathVariable String spaceId,@PathVariable String recurrenceId,HttpServletRequest r){parameters(r,Set.of("fromOrdinal"));UUID space=ScheduleRules.id(spaceId),id=ScheduleRules.id(recurrenceId);authorize(space,r,false,parent(r));metrics.counter("brain.planning.recurrence.reads","type","cancellation").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.cancellation(space,id,(int)number(r.getParameter("fromOrdinal"),1,100)));}
 @PostMapping("/{recurrenceId}/cancel") ResponseEntity<RecurrenceStore.Series> cancel(@PathVariable String spaceId,@PathVariable String recurrenceId,HttpServletRequest r)throws IOException{parameters(r,Set.of());UUID space=ScheduleRules.id(spaceId),id=ScheduleRules.id(recurrenceId);String trace=parent(r);var actor=authorize(space,r,true,trace);long version=version(r);var b=body(r);if(b.size()!=2||!b.path("fromOrdinal").isIntegralNumber()||!b.path("fromOrdinal").canConvertToInt()||!b.path("cancellationHash").isString())throw ScheduleRules.bad();var v=store.cancel(space,id,actor,version,b.path("fromOrdinal").asInt(),b.path("cancellationHash").asString(),trace.substring(3,35));metrics.counter("brain.planning.recurrence.changes","type","retired").increment();return response(v);}
}
